// Layout primitive (Category B) — arrangement only, owns no look.
// Carve-out 5 (component-contract.md §6): no Cmp token layer; it reads only its own
// `--sd-layout-*` inline intermediate.
//
// Constrains arbitrary content to a width/height ratio. This is the Layout tier by the
// AGENTS.md ladder (#1): it positions content it does not render, and owns no look.
// `ratio` is a plain number rather than a token scale because that is what every peer with
// this primitive does — shadcn (`ratio={16 / 9}`), Radix, and Carbon all take the division,
// and none of them tokenize it. A ratio is a per-usage composition choice, not a shared
// scale the way space or radius are.
import type { CSSProperties, HTMLAttributes, Ref } from "react";
import "./AspectRatio.css";

export interface AspectRatioProps extends Omit<HTMLAttributes<HTMLDivElement>, "className"> {
  /** Width divided by height — pass the division itself, e.g. `16 / 9`. Defaults to 1 (square). */
  ratio?: number;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLDivElement>;
}

export function AspectRatio({ ratio = 1, className, style, ...props }: AspectRatioProps) {
  return (
    <div
      {...props}
      className={className ? `sd-aspect-ratio ${className}` : "sd-aspect-ratio"}
      style={{ "--sd-layout-aspect-ratio": String(ratio), ...style } as CSSProperties}
    />
  );
}

/* AspectRatio.css — .sd-aspect-ratio
   Layout primitive: arrangement only, no look (no color/border/radius). Carve-out 5. */
.sd-aspect-ratio {
  /* Block inheritance of the inline per-instance --sd-layout-* var (see Container.css): custom
     properties inherit, so a nested AspectRatio with no `ratio` would otherwise pick up its
     ancestor's ratio instead of falling back to square. */
  --sd-layout-aspect-ratio: initial;
  /* grid, so a single child fills the box on both axes without this rule having to reach the
     child — descendant combinators are forbidden (§6 rule 2), so the box can only govern
     itself. The consumer sets `object-fit` on its own image, exactly as shadcn's example does.
     The `minmax(0, …)` on the single cell is load-bearing, not decoration. A bare `1fr` is
     shorthand for `minmax(auto, 1fr)`, and that `auto` minimum makes the track grow to its
     content — so a 1:1 image in a 16/9 box kept its natural height, overflowed, and got
     top-cropped by the clip below instead of being covered (measured 360×360 inside a 360×203
     box; `minmax(0, 1fr)` gives 360×203). Pinning the minimum to 0 lets the track take its size
     from the container, whose height `aspect-ratio` makes definite, so a child's percentage
     height resolves and `object-fit` finally has the box it expects. */
  display: grid;
  grid-template: minmax(0, 1fr) / minmax(0, 1fr);
  aspect-ratio: var(--sd-layout-aspect-ratio, 1);
  /* Clipping IS the ratio contract — without it, content larger than the box escapes and the
     ratio stops meaning anything. Not "look": the forbidden properties for a Layout primitive
     are color/border/radius, and both media boxes this replaces already clipped. */
  overflow: hidden;
}
